package com.library.server.service.impl; import com.library.common.exception.BusinessException; import com.library.common.model.PageResult; import com.library.pojo.dto.BookQuery; import com.library.pojo.entity.Book; import com.library.pojo.vo.BookVO; import com.library.server.mapper.BookMapper; import com.library.server.service.BookService; import org.springframework.stereotype.Service; import java.util.List; import java.util.Map;
@Service public class BookServiceImpl implements BookService { private final BookMapper mapper; public BookServiceImpl(BookMapper mapper){this.mapper=mapper;} public PageResult<BookVO> page(BookQuery q){BookQuery x=q==null?new BookQuery(1,10,null,null,null):q; int p=x.page()==null?1:x.page();int s=x.size()==null?10:x.size();return new PageResult<>(mapper.count(x.keyword(),x.categoryId(),x.status()),p,s,mapper.page(x.keyword(),x.categoryId(),x.status(),x.offset(),x.limit()));} public Book get(Long id){return mapper.findById(id);} public void save(Book b){if(b.getTotalStock()==null)b.setTotalStock(0);b.setAvailableStock(b.getTotalStock());b.setStatus(b.getAvailableStock()>0?1:2);mapper.insert(b);} public void update(Book b){mapper.update(b);} public void delete(Long id){mapper.delete(id);} public List<Map<String,Object>> stats(){return mapper.categoryStats();} }
